/* بيانات باب jud: تُحمَّل عند أول فتح للقسم */
window.JUD = {"ch":[{"id":"qaddam","t":"يا ليتني قدّمت لحياتي","d":"الآيات التي تجعل المال والجهد والوقت زاداً يُقدَّم للحياة الحقيقية في الآخرة: قول الإنسان «يا ليتني قدّمت لحياتي»، وطلب التقديم لغدٍ، وتمنّي المحتضر أن يتصدّق، وبقاء ما قُدِّم عند الله."},{"id":"jud","t":"حقيقة الجود والإنفاق","d":"الآيات التي رغّبت في الإنفاق ووصفت المنفقين: مثل الحبة التي تنبت سبع سنابل، والصدقة سرّاً وعلانية، والإنفاق في السراء والضراء، ووقاية شحّ النفس، وكون المال مستخلَفاً فيه، والقرض الحسن، وطيّب الكسب."},{"id":"adab","t":"آداب العطاء","d":"الآيات التي بيّنت ما يصون العطاء ويُتمّه: ترك المنّ والأذى، والإخلاص لوجه الله، والاقتصاد بين الإسراف والتقتير، والقول المعروف حين لا يتيسّر العطاء."},{"id":"ahl","t":"أهل الحاجة وحقّهم في المال","d":"الآيات التي سمّت من يُنفَق عليهم: الفقراء والمساكين وسائر مصارف الصدقات، والسائل والمحروم، والفقير المتعفّف، واليتيم وماله، والأيامى ومن فقد الزوج، والأسير والمسكين."},{"id":"qudwa","t":"نماذج الجود والإيثار","d":"ما ذكره القرآن من صور الجود في الأخيار: إيثار الأنصار، وإكرام إبراهيم عليه السلام ضيفه، وسقي موسى عليه السلام للمرأتين، والإنفاق مع التقوى في سورة الليل، والتأسّي برسول الله ﷺ."},{"id":"jaza","t":"ثمرة الجود وعاقبة البخل","d":"الآيات التي بيّنت ما يعود على المنفق من الخلف والتجارة التي لا تبور وطهارة النفس، وبقاء أثر الخير بعد الموت، وفي المقابل ما ورد في البخل والكنز ومنع المساكين."}],"tp":[{"id":"layt","ch":"qaddam","t":"«يا ليتني قدّمت لحياتي»","e":"تمنّي الإنسان يوم القيامة أن لو قدّم لحياته الحقيقية ما ينفعه.","ay":[[89,21,24]],"q":[{"bk":"saadi","s":89,"ay":24,"x":"{يا ويلتى لَيۡتَني لم أتَّخِذۡ فلاناً خليلاً}، وفي هذا دليلٌ على أنَّ الحياة التي ينبغي السعي في كمالها وتحصيلها وكمالها وفي تتميم لَذَّاتها هي الحياة في دار القرار؛ فإنَّها دارُ الخُلد والبقاء.","w":"السعدي","en":"[\"Woe to me! Would that I had not taken so-and-so as a friend\"]. In this is evidence that the life one should strive to perfect, to attain and to complete in its delights is the life in the abode of permanence, for it is the abode of eternity and endurance."}],"h":["qaddam","mali"]},{"id":"ghad","ch":"qaddam","t":"«ولتنظر نفس ما قدّمت لغد»","e":"الأمر بالنظر فيما قُدِّم لغدٍ ومحاسبة النفس.","ay":[[59,18,18]],"q":[{"bk":"saadi","s":59,"ay":18,"x":"وهذه الآية الكريمةُ أصلٌ في محاسبة العبد نفسَه، وأنَّه ينبغي له أن يتفقَّدها؛ فإنْ رأى زللاً؛ تداركه بالإقلاع عنه والتوبة النصوح والإعراض عن الأسباب الموصلة إليه، وإن رأى نفسه مقصراً في أمر من أوامر الله؛ بذل جهدَه واستعانَ بربِّه في تتميمه وتكميله وإتقانه، ويقايس بين منن الله عليه وإحسانه وبين تقصيرِهِ؛ فإن ذلك يوجب له الحياء لا محالة.","w":"السعدي","en":"This noble verse is a foundation for a servant holding himself to account and checking on himself. If he sees a slip, he remedies it by abandoning it, sincere repentance and turning away from what leads to it; and if he sees himself falling short in some command of Allah, he exerts his effort and seeks his Lord's help to complete it and perfect it. He compares Allah's favors and kindness to him with his own shortcoming, and that inevitably brings him a sense of shame."}],"h":[]},{"id":"lawla","ch":"qaddam","t":"«لولا أخّرتني إلى أجل قريب فأصّدّق»","e":"طلب المحتضر أن يؤخَّر ليتصدّق، وأمر المؤمنين بالإنفاق قبل الموت.","ay":[[63,9,11]],"q":[{"bk":"saadi","s":63,"ay":10,"x":"وقوله: {وأنفقوا ممَّا رَزَقۡنَاكُم}: يدخلُ في هذه النفقات الواجبة من الزكاة والكفارات ، ونفقة الزوجات والمماليك، ونحو ذلك، والنفقات المستحبَّة؛ كبذل المال في جميع المصالح، وقال:{ممَّا رَزَقۡناكم}: ليدلَّ ذلك على أنَّه تعالى لم يكلِّف العباد من النفقة ما يُعْنِتُهُمْ ويشقُّ عليهم، بل أمرهم بإخراج جزءٍ ممَّا رزقهم ويسَّره ويسَّر أسبابه، فليشكروا الذي أعطاهم بمواساة إخوانهم المحتاجين، وليبادروا بذلك، الموت الذي إذا جاء؛ لم يمكن العبد أن يأتي بمثقال ذرَّة من الخير، ولهذا قال:{من قبل أن يأتيَ أحدَكم الموتُ فيقولَ}: متحسراً على ما فَرَّطَ في وقت الإمكان، سائلاً الرجعةَ التي هي محالٌ:{ربِّ لولا أخَّرۡتَني إلى أجل قريبٍ}؛ أي: لأتدارك ما فرَّطتُ فيه، {فأصَّدَّقَ}: من مالي ما به أنجو من العذاب، وأستحقُّ [به] جزيل الثواب، {وأكن من الصالحين} …","w":"السعدي","en":"His words \"and spend from what We have provided you\" include the obligatory spending such as zakat, expiations and maintenance of wives and those owned, and the recommended spending such as giving wealth for every good purpose. He said \"from what We have provided you\" to show that He did not burden people with spending that would distress them or be hard for them; He commanded them to give a portion of what He gave them and made it easy for them, and eased its means. So let them thank the One who gave them by comforting their needy brothers, and let them hasten to do so before death, which when it comes leaves a servant unable to bring even an atom's weight of good. That is why He said: \"before death comes to one of you and he says\" — in anguish over what he neglected while there was still a chance, asking for a return that is impossible — \"My Lord, if only You would delay me for a short term,\" that is, so that I could make up for what I neglected, \"so I would give charity\" from my wealth what would save me from punishment and earn me abundant reward, \"and be among the righteous\" …"},{"bk":"saadi","s":63,"ay":10,"x":"وهذا السؤال والتَّمني قد فات وقتُه، ولا يمكن تداركه، ولهذا قال:{ولن يؤخِّرَ اللهُ نفساً إذا جاء أجَلُها}: المحتوم لها.","w":"السعدي","en":"This question and wish has been missed; its time has passed and it can no longer be made good. Hence He said: \"And never will Allah delay a soul when its time has come\" — the decreed time for it."}],"h":[]},{"id":"taqdimu","ch":"qaddam","t":"«وما تقدّموا لأنفسكم من خير تجدوه عند الله»","e":"ما يقدّمه الإنسان لنفسه من خير يجده عند الله خيراً وأعظم أجراً.","ay":[[73,20,20]],"q":[{"bk":"saadi","s":73,"ay":20,"x":"ثم حثَّ على عموم الخير وأفعاله، فقال:{وما تقدِّموا لأنفسكم من خيرٍ تجِدوه عند الله هو خيراً وأعظم أجراً}: الحسنة بعشر أمثالها إلى سبعمائةِ ضعفٍ إلى أضعافٍ كثيرة.","w":"السعدي","en":"Then He urged general good and its deeds, saying: \"And whatever good you put forward for yourselves, you will find it with Allah, better and greater in reward\" — a good deed is multiplied tenfold, up to seven hundred times, up to many multiples."}],"h":[]},{"id":"anfiqu","ch":"qaddam","t":"«أنفقوا مما رزقناكم من قبل أن يأتي يوم لا بيع فيه»","e":"الأمر بالإنفاق قبل يوم لا بيع فيه ولا خلّة ولا شفاعة.","ay":[[2,254,254]],"q":[{"bk":"saadi","s":2,"ay":254,"x":"يحث الله المؤمنين على النفقات في جميع طرق الخير، لأن حذف المعمول يفيد التعميم، ويذكرهم نعمته عليهم بأنه هو الذي رزقهم ونوَّع عليهم النعم، وأنه لم يأمرهم بإخراج جميع ما في أيديهم بل أتى بِمِنْ الدالة على التبعيض، فهذا مما يدعوهم إلى الإنفاق، ومما يدعوهم أيضاً إخبارهم أن هذه النفقات مدخرة عند الله في يوم لا تفيد فيه المعاوضات بالبيع ونحوه ولا التبرعات ولا الشفاعات فكل أحد يقول ما قدمت لحياتي، فتنقطع الأسباب كلها إلا الأسباب المتعلقة بطاعة الله والإيمان به يوم لا ينفع مال ولا بنون إلا من أتى الله بقلب سليم.","w":"السعدي","en":"Allah urges the believers to spend in all ways of good, because omitting the object of the verb gives it general scope. He reminds them of His favor, that He is the One who provided for them and gave them many kinds of blessings, and that He did not command them to give out everything they have, using \"min\" which indicates a part. That calls them to spend. Also calling them is the news that this spending is stored with Allah on a day when neither exchange by sale and the like, nor gifts, nor intercessions will avail, when everyone will say \"what I sent ahead for my life\", and all means are cut off except those connected to obedience to Allah and faith in Him, on a day when neither wealth nor children will benefit except one who comes to Allah with a sound heart."}],"h":["shiqq"]},{"id":"habba","ch":"jud","t":"«كمثل حبة أنبتت سبع سنابل»","e":"مثل نماء النفقة في سبيل الله بالحبة التي تنبت سبع سنابل.","ay":[[2,261,261]],"q":[{"bk":"saadi","s":2,"ay":261,"x":"هذا حث عظيم من الله لعباده في إنفاق أموالهم في سبيله، وهو طريقه الموصل إليه، فيدخل في هذا إنفاقه في ترقية العلوم النافعة، وفي الاستعداد للجهاد في سبيله، وفي تجهز المجاهدين وتجهيزهم، وفي جميع المشاريع الخيرية النافعة للمسلمين، ويلي ذلك الإنفاق على المحتاجين والفقراء والمساكين، وقد يجتمع الأمران فيكون في النفقة دفع الحاجات والإعانة على الخير والطاعات، فهذه النفقات مضاعفة هذه المضاعفة بسبعمائة إلى أضعاف أكثر من ذلك، ولهذا قال:{والله يضاعف لمن يشاء}؛ وذلك بحسب ما يقوم بقلب المنفق من الإيمان والإخلاص التام وفي ثمرات نفقته ونفعها، فإن بعض طرق الخيرات يترتب على الإنفاق فيها منافع متسلسلة ومصالح متنوعة فكان الجزاء من جنس العمل.","w":"السعدي","en":"This is a great urging from Allah to His servants to spend their wealth in His way, which is the path that leads to Him. It includes spending on advancing beneficial knowledge, preparing for jihad in His way, equipping the fighters, and on all charitable projects that benefit the Muslims; and next comes spending on the needy, the poor and the destitute. The two may be combined, so that the spending meets needs and also helps toward good and acts of obedience. This spending is multiplied in this way, seven hundredfold to many more times than that; hence He said: \"and Allah multiplies for whom He wills\". That depends on what is in the heart of the spender of faith and complete sincerity, and on the fruits of his spending and its benefit; for some paths of good bring continuing benefits and varied interests from spending on them, so the reward is of the same kind as the deed."}],"h":["khalaf","naqas"]},{"id":"khafa","ch":"jud","t":"الصدقة سرّاً وعلانية","e":"الصدقة المخفاة والمعلنة والليل والنهار.","ay":[[2,271,271],[2,274,274]],"q":[{"bk":"saadi","s":2,"ay":271,"x":"وأخبر أن الصدقة إن أبداها المتصدق فهي خير، وإن أخفاها وسلمها للفقير كان أفضل، لأن الإخفاء على الفقير إحسان آخر، وأيضاً فإنه يدل على قوة الإخلاص. وأحد السبعة الذين يظلهم الله في ظله من تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، وفي قوله:{وإن تخفوها وتؤتوها الفقراء فهو خير لكم}؛ فائدة لطيفة، وهو أن إخفاءها خير من إظهارها إذا أعطيت الفقير.","w":"السعدي","en":"He informed that if the giver of charity makes it public it is good, and if he conceals it and hands it to the poor person it is better, because concealing it from the poor is another act of kindness, and it also shows strength of sincerity. It is one of the seven whom Allah will shade in His shade: the one who gives charity and conceals it so that his left hand does not know what his right hand spends. In His words \"and if you conceal it and give it to the poor, it is better for you\" there is a subtle benefit: concealing charity is better than showing it when it is given to a poor person."}],"h":["sirr"]},{"id":"saraa","ch":"jud","t":"«الذين ينفقون في السراء والضراء»","e":"وصف المتقين بالإنفاق في اليسر والعسر.","ay":[[3,133,134]],"q":[{"bk":"saadi","s":3,"ay":134,"x":"ثم وصف المتقين وأعمالهم فقال: {الذين ينفقون في السراء والضراء}؛ أي: في حال عسرهم ويسرهم إن أيسروا أكثروا من النفقة وإن أعسروا لم يحتقروا من المعروف شيئاً ولو قل، {والكاظمين الغيظ}: أي: إذا حصل لهم من غيرهم أذية توجب غيظهم، وهو امتلاء قلوبهم من الحنق الموجب للانتقام بالقول والفعل.","w":"السعدي","en":"Then He described the people of taqwa and their deeds, saying: \"Those who spend in ease and hardship\", that is, in both their hardship and their ease: if they are well off they spend much, and if they are in difficulty they do not belittle any kindness, however small; \"and those who restrain anger\", that is, when others harm them in a way that provokes their anger — which is a heart filled with rage that calls for revenge by word and deed."}],"h":[]},{"id":"shuhh","ch":"jud","t":"«ومن يوق شحّ نفسه فأولئك هم المفلحون»","e":"الأمر بالإنفاق وبيان أن وقاية شحّ النفس سبب الفلاح.","ay":[[64,16,16]],"q":[{"bk":"saadi","s":64,"ay":16,"x":"وقوله:{واسمعوا}؛ أي: اسمعوا ما يعِظُكم الله به وما يَشْرَعُه لكم من الأحكام واعلموا ذلك وانقادوا له، {وأطيعوا}: الله ورسولَه في جميع أموركم، {وأنفِقوا}: من النفقات [الشرعية] الواجبة والمستحبَّة؛ يَكُنْ ذلك الفعل منكم خيراً لكم في الدُّنيا والآخرة؛ فإنَّ الخير كلَّه في امتثال أوامر الله [تعالى] وقَبول نصائحه والانقياد لشرعه، والشرَّ كلَّه في مخالفة ذلك، ولكن ثَمَّ آفةٌ تمنعُ كثيراً من الناس من النفقة المأمور بها، وهو الشحُّ المجبولة عليه أكثر النفوس؛ فإنَّها تشحُّ بالمال وتحبُّ وجوده وتكره خروجه من اليد غاية الكراهة، فمن وقاه اللَّهُ [تعالى]{شُحَّ نفسِه}: بأن سمحت نفسه بالإنفاق النافع لها، {فأولئك هم المفلحونَ}: لأنَّهم أدركوا المطلوب ونجوا من المرهوب، بل لعلَّ ذلك شاملٌّ لكلِّ ما أمر به العبدُ ونهي عنه …","w":"السعدي","en":"His words \"and listen\" mean: listen to what Allah admonishes you with and to the rulings He legislates for you, know them and submit to them; \"and obey\" Allah and His Messenger in all your affairs; \"and spend\" from the obligatory and recommended expenditures — that deed will be better for you in this world and the next. All good lies in following the commands of Allah, accepting His advice and submitting to His law, and all evil in opposing that. But there is a plague that keeps many people from the spending they are commanded to give: the miserliness (shuhh) that most souls are created with. The soul is stingy with wealth, loves having it and strongly dislikes it leaving the hand. Whoever Allah guards from the miserliness of his soul, so that his soul is generous in spending that benefits it, \"those are the successful\" — for they attain what is sought and are safe from what is feared; indeed this may extend to everything a servant is commanded or forbidden …"}],"h":[]},{"id":"mustakhlaf","ch":"jud","t":"«وأنفقوا مما جعلكم مستخلفين فيه»","e":"الأمر بالإنفاق مما جعل الله الناس مستخلَفين فيه وجزاء المنفقين.","ay":[[57,7,10]],"q":[{"bk":"saadi","s":57,"ay":7,"x":"يأمر تعالى عبادَه بالإيمان به، وبرسوله وبما جاء به، وبالنفقة في سبيله من الأموال التي جعلها الله في أيديهم واستخْلَفَهم عليها؛ لينظر كيف يعملونَ. ثم لمَّا أمرهم بذلك؛ رغَّبهم وحثَّهم عليه بذكر ما رتَّب عليه من الثواب، فقال:{فالذين آمنوا منكم وأنفقوا لهم أجرٌ كبيرٌ}؛ أي: الذين جمعوا بين الإيمان بالله ورسوله والنفقة في سبيله لهم أجرٌ كبيرٌ، أعظمه وأجلُّه رِضا ربِّهم والفوزُ بدار كرامته وما فيها من النعيم المقيم الذي أعدَّه الله للمؤمنين والمجاهدين.","w":"السعدي","en":"Allah commands His servants to believe in Him, in His Messenger and in what he brought, and to spend in His way from the wealth that Allah placed in their hands and made them stewards over, \"that He may see how you act\". Then, having commanded that, He encouraged and urged them with the reward that follows it, saying: \"So those who have believed among you and spent will have a great reward\", that is, those who combine belief in Allah and His Messenger with spending in His way have a great reward, the greatest and most exalted of which is their Lord's pleasure and success in the abode of His honor, with the lasting bliss that Allah prepared for the believers and the fighters."}],"h":["fadl2"]},{"id":"qard","ch":"jud","t":"«من ذا الذي يقرض الله قرضاً حسناً»","e":"تسمية النفقة قرضاً حسناً يضاعفه الله.","ay":[[2,245,245],[57,11,11]],"q":[{"bk":"saadi","s":2,"ay":245,"x":"وتأمل هذا الحث اللطيف على النفقة وإن المنفق قد أقرض الله الملي الكريم ووعده المضاعفة الكثيرة كما قال تعالى:{مثل الذين ينفقون أموالهم في سبيل الله كمثل حبة أنبتت سبع سنابل في كل سنبلة مائة حبة، والله يضاعف لمن يشاء والله واسع عليم}؛ ولما كان المانع الأكبر من الإنفاق خوفَ الإملاقِ أخبر تعالى أنَّ الغنى والفقرَ بيد الله، وأنه يقبض الرزق على من يشاء ويبسطه على من يشاء، فلا يتأخر من يريد الإنفاق خوفَ الفقر، ولا يظن أنه ضائع، بل مرجع العباد كلهم إلى الله فيجد المنفقون والعاملون أجرهم عنده مدخراً أحوج ما يكونون إليه، ويكون له من الوقع العظيم ما لا يمكن التعبير عنه …","w":"السعدي","en":"Consider this gentle urging to spend: the one who spends has lent to Allah, the Rich and Generous, who has promised him great multiplication, as He said: \"The example of those who spend their wealth in the way of Allah is like a grain that grows seven ears; in each ear is a hundred grains, and Allah multiplies for whom He wills; and Allah is All-Encompassing and Knowing.\" Since the greatest obstacle to spending is the fear of poverty, He told that wealth and poverty are in Allah's hand, and that He constricts provision for whom He wills and expands it for whom He wills; so one who wants to spend should not hold back for fear of poverty, nor think that it is lost. Rather, all servants return to Allah, and those who spend and those who work will find their reward stored with Him, when they are most in need of it, and it will have a great effect that cannot be expressed …"}],"h":[]},{"id":"tayyib","ch":"jud","t":"«أنفقوا من طيّبات ما كسبتم»","e":"الإنفاق من طيّب الكسب وترك قصد الخبيث، والداعيان: داعي الرحمن وداعي الشيطان.","ay":[[2,267,267]],"q":[{"bk":"saadi","s":2,"ay":267,"x":"ويدخل في عمومها الفرض والنفل، وأمر تعالى أن يقصدوا الطيب منها ولا يقصدوا الخبيث وهو الرديء الدون يجعلونه لله، ولو بذله لهم من لهم حق عليه لم يرتضوه، ولم يقبلوه إلا على وجه المغاضاة والإغماض، فالواجب إخراج الوسط من هذه الأشياء والكمال إخراج العالي، والممنوع إخراج الرديء فإن هذا لا يجزي عن الواجب، ولا يحصل فيه الثواب التام في المندوب.","w":"السعدي","en":"It includes the obligatory and the voluntary. He commanded them to aim for the good part of it and not aim at the bad, which is the poor and worthless, offering it to Allah — which, if given to them by someone whose right it is, they would not accept except with closed eyes and reluctance. So the obligation is to give the average of these things, and perfection is to give the best; giving the poor-quality is forbidden, for it does not satisfy the obligation, and complete reward is not gained in voluntary giving."},{"bk":"saadi","s":2,"ay":267,"x":"فلما حثهم على الإنفاق النافع نهاهم عن الإمساك الضار، وبين لهم أنهم بين داعيين: داعي الرحمن يدعوهم إلى الخير ويعدهم عليه الخير والفضل والثواب العاجل والآجل وإخلاف ما أنفقوا، وداعي الشيطان الذي يحثهم على الإمساك، ويخوفهم إن أنفقوا أن يفتقروا.","w":"السعدي","en":"Having urged them to beneficial spending, He forbade them harmful withholding, and showed them that they are between two callers: the caller of the Most Merciful, who calls them to good and promises them good, bounty, and reward both near and far, and the replacement of what they spent; and the caller of Satan, who urges them to withhold and frightens them that if they spend they will become poor."}],"h":[]},{"id":"mann","ch":"adab","t":"«لا تبطلوا صدقاتكم بالمنّ والأذى»","e":"إبطال الصدقة بالمنّ والأذى وضرب الأمثال في الإنفاق.","ay":[[2,262,264]],"q":[{"bk":"saadi","s":2,"ay":264,"x":"فأما الأول فإنه لما كانت نفقته مقبولة مضاعفة لصدورها عن الإيمان والإخلاص التام {ابتغاء مرضاة الله وتثبيتاً من أنفسهم}؛ أي: ينفقون وهم ثابتون على وجه السماحة والصدق فمثل هذا العمل، {كمثل جنة بربوة}؛ وهو المكان المرتفع لأنه يتبين للرياح والشمس، والماء فيها غزير، فإن لم يصبها ذلك الوابل الغزير، حصل لها طلٌّ كافٍ لطيب منبتها وحسن أرضها وحصول جميع الأسباب الموفرة لنموها وازدهارها وإثمارها، ولهذا {آتت أكلها ضعفين}؛ أي: متضاعفاً، وهذه الجنة التي على هذا الوصف هي أعلى ما يطلبه الناس، فهذا العمل الفاضل بأعلى المنازل.","w":"السعدي","en":"As for the first: since his spending is accepted and multiplied because it comes from faith and complete sincerity, \"seeking the approval of Allah and certainty from themselves\" — that is, they spend steadfast, with generosity and truthfulness — such a deed is \"like a garden on a height\", a raised place that is exposed to winds, sun and water. Its water is abundant, and if the heavy downpour does not reach it, a light dew is enough for the goodness of its soil and the quality of its ground, with all the means for its growth, flourishing and fruiting. Hence \"it brought forth its fruit twofold\", that is, multiplied. A garden of this description is the highest that people seek; so this noble deed is of the highest rank."},{"bk":"saadi","s":2,"ay":264,"x":"وأما من أنفق لله ثم أتبع نفقته منًّا وأذى، أو عمل عملاً فأتى بمبطل لذلك العمل فهذا مثله مثال صاحب هذه الجنة، لكن سلط عليها {إعصار}؛ وهو الريح الشديدة {فيه نار فاحترقت}؛ وله ذرية ضعفاء وهو ضعيف قد أصابه الكبر، فهذه الحال من أفظع الأحوال، ولهذا صدَّر هذا المثل بقوله:{أيود أحدكم}؛ إلى آخرها بالاستفهام المتقرر عند المخاطبين فظاعته، فإن تَلَفَها دفعة واحدة بعد زهاء أشجارها وإيناع ثمارها مصيبة كبرى، ثم حصول هذه الفاجعة وصاحبها كبير قد ضعف عن العمل وله ذرية ضعفاء لا مساعدة منهم له ومؤنتهم عليه فاجعة أخرى، فصار صاحب هذا المثل الذي عمل لله ثم أبطل عمله بمنافٍ له يشبه حال صاحب الجنة التي جرى عليها ما جرى حين اشتدت ضرورته إليها.","w":"السعدي","en":"As for the one who spent for Allah and then followed his spending with reproach and injury, or did some deed that nullified it, his likeness is that of the owner of this garden, upon which a \"whirlwind\", a violent wind, was sent, \"containing fire, so it was burned\", while he has weak offspring and is himself weak, stricken by old age. This is one of the most terrible of situations, which is why this parable opens with a question whose horror is understood by those addressed: \"Would any of you like...\" Its destruction all at once, after the trees were lush and the fruit ripe, is a great calamity; and then this disaster befalling an old man too weak to work, with weak children who cannot help him and whose upkeep falls on him, is another calamity. So the one for whom the parable is made, who worked for Allah and then nullified his work with something contrary to it, is like the owner of the garden when what happened to it happened at the moment he was most in need of it."}],"h":[]},{"id":"ikhlas","ch":"adab","t":"«إنما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكوراً»","e":"الإطعام لوجه الله لا لجزاء ولا شكور.","ay":[[76,9,9],[2,265,265]],"q":[{"bk":"saadi","s":76,"ay":8,"x":"{ويطعِمونَ الطَّعامَ على حبِّه}؛ أي: وهم في حال يحبُّون فيها المال والطعام، لكنَّهم قدَّموا محبَّة الله على محبَّة نفوسهم، ويتحرَّوْن في إطعامهم أولى الناس وأحوجَهم، {مسكيناً ويتيماً وأسيراً}: ويقصدون بإنفاقهم وإطعامهم وجهَ الله تعالى، ويقولون بلسان الحال:{إنَّما نطعِمُكم لوجه الله لا نريدُ منكم جزاءً ولا شكوراً}؛ أي: لا جزاءً ماليًّا ولا ثناءً قوليًّا، {إنا نخاف من ربِّنا يوماً عبوساً}؛ أي: شديد الجهمة والشرِّ، {قمطريراً}؛ أي: ضنكاً ضيقاً.","w":"السعدي","en":"\"And they feed food despite their love for it\" — that is, they are in a state of loving wealth and food, yet they put the love of Allah before the love of their own selves, and they carefully seek out the most deserving and needy people to feed, \"the needy, the orphan and the captive\", and with their spending and feeding they intend the face of Allah, saying by their condition: \"We feed you only for the face of Allah; we wish for no reward or thanks from you\", that is, no repayment in wealth and no praise in words. \"Indeed, we fear from our Lord a Day austere and distressful\", that is, extremely grim and evil, \"distressful\", narrow and tight."}],"h":[]},{"id":"iqtisad","ch":"adab","t":"الاقتصاد في الجود: «ولا تجعل يدك مغلولة»","e":"وصف عباد الرحمن في الإنفاق بين الإسراف والتقتير، والنهي عن غلّ اليد وبسطها كل البسط.","ay":[[17,29,29],[25,67,67]],"q":[{"bk":"saadi","s":17,"ay":29,"x":"وقال هنا: {ولا تجعل يَدَكَ مغلولةً إلى عنقك}: كناية عن شدة الإمساك والبخل، {ولا تَبۡسُطۡها كلَّ البسط}: فتنفق فيما لا ينبغي أو زيادة على ما ينبغي، {فتقعدَ}: إن فعلت ذلك {مَلوماً}؛ أي: تُلام على ما فعلتَ، {مَحۡسوراً}؛ أي: حاسر اليد فارغها؛ فلا بقي ما في يدك من المال، ولا خَلَفَه مدحٌ وثناءٌ.","w":"السعدي","en":"And He said here: \"And do not make your hand shackled to your neck\", an expression for extreme withholding and miserliness, \"nor extend it completely\", spending on what you should not or more than you should, \"so you would become blamed\", that is, you are blamed for what you did, \"insolvent\", that is, with empty hands: neither what is in your hand remains, nor does praise and commendation replace it."},{"bk":"saadi","s":25,"ay":67,"x":"{والذين إذا أنفَقوا}: النفقاتِ الواجبةَ والمستحبةَ {لم يُسۡرِفوا}: بأن يَزيدوا على الحدِّ فيدخُلوا في قسم التبذير، {ولم يَقۡتُروا}: فيدخلوا في باب البُخْل والشُّحِّ، وإهمال الحقوق الواجبة، {وكان}: إنفاقُهم {بينَ ذلك}: بين الإسراف والتقتير {قَواماً}: يبذُلون في الواجبات من الزَّكَواتِ والكفاراتِ والنفقاتِ الواجبةِ وفيما ينبغي على الوجه الذي يَنْبَغي من غير ضررٍ ولا ضِرارٍ، وهذا من عدلهم واقتصادهم.","w":"السعدي","en":"\"And those who, when they spend\" — the obligatory and the recommended spending — \"are neither extravagant\" by exceeding the limit and falling into wastefulness, \"nor stingy\" and falling into miserliness and neglect of obligatory rights, \"and it is between that\" — between extravagance and niggardliness — \"a medium\". They spend on obligatory things such as zakat, expiations and obligatory maintenance, and on what is appropriate in the proper way, without harm or injury; and this is from their justice and moderation."}],"h":[]},{"id":"maruf","ch":"adab","t":"«قول معروف ومغفرة خير من صدقة يتبعها أذى»","e":"الإحسان بالقول المعروف حين يتعذّر العطاء، ومراتب الإحسان.","ay":[[2,263,263],[17,28,28]],"q":[{"bk":"saadi","s":2,"ay":263,"x":"ذكر الله أربع مراتب للإحسان: المرتبة العليا: النفقة الصادرة عن نية صالحة ولم يتبعها المنفق منًّا ولا أذى. ثم يليها قول المعروف وهو الإحسان القولي بجميع وجوهه الذي فيه سرور المسلم، والاعتذار من السائل إذا لم يوافق عنده شيئاً، وغير ذلك من أقوال المعروف. والثالثة الإحسان بالعفو والمغفرة عمن أساء إليك بقول أو فعل. وهذان أفضل من الرابعة وخير منها وهي: التي يتبعها المتصدق الأذى للمعطي لأنه كدر إحسانه وفعل خيراً وشرًّا.","w":"السعدي","en":"Allah mentioned four ranks of kindness. The highest rank: spending that comes from a good intention and is not followed by the giver with reproach or injury. Next comes good speech, which is kindness in words in all its forms that brings joy to a Muslim, including apologizing to the one who asks when one has nothing to give him, and other good words. The third is kindness through pardon and forgiveness toward one who wronged you by word or deed. These two are better than the fourth and superior to it, which is charity that the giver follows with injury to the recipient, because he has muddied his kindness and has done both good and bad."},{"bk":"saadi","s":17,"ay":29,"x":"أي: لطيفاً برفقٍ ووعد بالجميل عند سُنوح الفرصة واعتذارٍ بعدم الإمكان في الوقت الحاضر؛ لينقلبوا عنك مطمئنَّة خواطرهم؛ كما قال تعالى:{قولٌ معروفٌ ومغفرةٌ خيرٌ من صدقةٍ يَتۡبَعُها أذى}: وهذا أيضاً من لطف الله تعالى بالعباد، أمرهم بانتظار الرحمة والرزق منه؛ لأنَّ انتظار ذلك عبادة، وكذلك وعدُهم بالصدقة والمعروف عند التيسُّر عبادةٌ حاضرةٌ؛ لأنَّ الهمَّ بفعل الحسنة حسنةٌ، ولهذا ينبغي للإنسان أن يفعل ما يَقْدِرُ عليه من الخير، وينوي فعل ما لم يقدِرْ عليه لِيُثاب على ذلك، ولعلَّ الله ييسِّر له بسبب رجائه.","w":"السعدي","en":"That is, gently, with kindness and a promise of good when opportunity comes, and an apology that it is not possible at present, so that their hearts go back at ease; as Allah said: \"A kind word and forgiveness are better than charity followed by injury\". This too is from Allah's gentleness with His servants: He told them to await mercy and provision from Him, for awaiting that is worship, and likewise promising them charity and good when it becomes easy is a present act of worship, because merely intending a good deed is itself a good deed. So a person should do what he is able of good and intend to do what he cannot, so that he is rewarded for it, and perhaps Allah will make it easy for him because of his hope."}],"h":[]},{"id":"asnaf","ch":"ahl","t":"مصارف الصدقات: «إنما الصدقات للفقراء والمساكين»","e":"أصناف من تُصرف إليهم الزكاة.","ay":[[9,60,60]],"q":[{"bk":"saadi","s":9,"ay":60,"x":"يقول تعالى: {إنَّما الصدقات}؛ أي: الزكوات الواجبة، بدليل أن الصَّدقة المستحبَّة لكل أحدٍ لا يخصُّ بها أحدٌ دون أحدٍ؛ [أي]: {إنَّما الصَّدقات}: لهؤلاء المذكورين دون مَنْ عداهم؛ لأنه حصرها فيهم، وهم ثمانية أصناف: الأول والثاني: الفقراء والمساكين، وهم في هذا الموضع صنفان متفاوتان؛ فالفقير أشدُّ حاجةً من المسكين؛ لأنَّ الله بدأ بهم، ولا يُبدأ إلا بالأهمِّ فالأهمِّ؛ فَفُسِّرَ الفقير بأنه الذي لا يجد شيئاً أو يجد بعض كفايته دون نصفها، والمسكين الذي يجد نصفها فأكثر، ولا يجد تمام كفايته؛ لأنَه لو وجدها؛ لكان غنيًّا، فيعطَون من الزكاة ما يزول به فقرهم ومسكنتهم.","w":"السعدي","en":"Allah says: \"Zakat expenditures are only for...\" — that is, the obligatory zakat, since voluntary charity may be given to anyone without restriction. Zakat is for these mentioned categories and not for others, since He limited it to them, and they are eight categories. The first and second: the poor and the needy, who in this place are two distinct groups. The poor person is in greater need than the needy one, because Allah began with them, and He begins only with the most important first. The poor person is explained as one who finds nothing, or finds some of his sufficiency, less than half; and the needy one as one who finds half or more but not the whole of what suffices him, for if he found it he would be wealthy. So they are given from zakat what removes their poverty and neediness."},{"bk":"saadi","s":9,"ay":60,"x":"الخامس: الرقاب، وهم المكاتَبون الذين قد اشتروا أنفسَهم من ساداتهم؛ فهم يسعَوْن في تحصيل ما يفكُّ رقابَهم، فيعانون على ذلك من الزكاة. وفكُّ الرقبة المسلمة التي في حبس الكفار داخلٌ في هذا، بل أولى. ويدخل في هذا أنَّه يجوز أن يعتق [منها] الرقاب استقلالاً؛ لدخوله في قوله:{وفي الرِّقاب}.","w":"السعدي","en":"The fifth: \"in the freeing of necks\", those slaves who have contracted to buy their freedom from their masters; they strive to obtain what will free their necks, and are helped toward that from zakat. Freeing a Muslim neck held in captivity by unbelievers is included, indeed it has greater priority. It also includes that necks may be freed outright from it, since this falls under His words \"and for freeing slaves\"."}],"h":[]},{"id":"sail","ch":"ahl","t":"«وفي أموالهم حق للسائل والمحروم»","e":"جعل حق معلوم في أموال المتقين للسائل والمحروم.","ay":[[70,24,25],[51,19,19]],"q":[{"bk":"saadi","s":70,"ay":24,"x":"{والذين في أموالهم حقٌّ معلومٌ}: من زكاة وصدقة، {للسائل}: الذي يتعرَّض للسؤال، {والمحروم}: وهو المسكين الذي لا يسألُ الناس فيعطوه ولا يفطنُ له فيتصدَّق عليه.","w":"السعدي","en":"\"And those in whose wealth is a known right\": of zakat and charity, \"for the one who asks\", who exposes himself to asking, \"and the deprived\", who is the needy person who does not ask people so that they would give him, and nobody notices him so as to give him charity."},{"bk":"saadi","s":51,"ay":19,"x":"{وفي أموالهم حقٌّ}: واجبٌ ومستحبٌّ {للسائل والمحروم}؛ أي: للمحتاجين الذين يطلبون من الناس والذين لا يسألونهم.","w":"السعدي","en":"\"And in their wealth was a right\" — obligatory and recommended — \"for the one who asks and the deprived\", that is, for the needy who ask people and those who do not ask them."}],"h":["fadl"]},{"id":"taaffuf","ch":"ahl","t":"الفقير المتعفف: «يحسبهم الجاهل أغنياء من التعفف»","e":"الفقير الذي يمنعه التعفّف من السؤال وفضل الإنفاق عليه.","ay":[[2,273,273]],"q":[{"bk":"saadi","s":2,"ay":273,"x":"يعني أنه ينبغي أن تتحروا بصدقاتكم الفقراء الذين حبسوا أنفسهم في سبيل الله وعلى طاعته، وليس لهم إرادة في الاكتساب أو ليس لهم قدرة عليه وهم يتعففون إذا رآهم الجاهل ظن أنهم أغنياء {لا يسألون النّاس إلحافاً}؛ فهم لا يسألون بالكلية وإن سألوا اضطراراً لم يلحفوا في السؤال، فهذا الصنف من الفقراء أفضل ما وضعت فيهم النفقات لدفع حاجتهم وإعانة لهم على مقصدهم وطريق الخير وشكراً لهم على ما اتصفوا به من الصبر والنظر إلى الخالق لا إلى الخلق، ومع ذلك فالإنفاق في طرق الإحسان وعلى المحاويج حيثما كانوا فإنه خير وأجر وثواب عند الله ولهذا قال: {274}{الذين ينفقون أموالهم بالليل والنهار سراً وعلانية فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون} …","w":"السعدي","en":"That is, you should seek out for your charity the poor who have confined themselves to the way of Allah and obedience to Him, who have no intention of earning or have no ability to do so, and who restrain themselves so that an ignorant person who sees them thinks they are wealthy: \"They do not ask people persistently\". They do not ask at all, and if they ask out of necessity they do not press in asking. This kind of poor people is the best place to put spending to meet their need, to help them in their purpose and on the path of good, and as thanks for the patience and the looking to the Creator rather than creatures that they are characterized by. Even so, spending in ways of kindness and on the needy wherever they are is good and brings reward and recompense with Allah, which is why He said: \"274. Those who spend their wealth by night and by day, secretly and publicly, will have their reward with their Lord, and no fear will be upon them, nor will they grieve\" …"}],"h":["miskin"]},{"id":"yatimmal","ch":"ahl","t":"«ويسألونك عن اليتامى قل إصلاح لهم خير»","e":"الإصلاح لليتامى ومخالطتهم، والوعيد في أكل أموالهم ظلماً.","ay":[[2,220,220],[4,10,10]],"q":[{"bk":"saadi","s":2,"ay":220,"x":"لما نزل قوله تعالى: {إن الذين يأكلون أموال اليتامى ظلماً إنما يأكلون في بطونهم ناراً وسيصلون سعيراً}؛ شق ذلك على المسلمين وعزلوا طعامهم عن طعام اليتامى خوفاً على أنفسهم من تناولها ولو في هذه الحالة التي جرت العادة بالمشاركة فيها، وسألوا النبي - صلى الله عليه وسلم -، عن ذلك ، فأخبرهم تعالى أن المقصود إصلاح أموال اليتامى بحفظها وصيانتها والاتجار فيها، وأن خلطتهم إياهم في طعام وغيره جائز على وجه لا يضر باليتامى لأنهم إخوانكم ومن شأن الأخ مخالطة أخيه، والمرجع في ذلك إلى النية والعمل، فمن علم [اللهُ] من نيته أنه مصلح لليتيم وليس له طمع في ماله فلو دخل عليه شيء من غير قصد لم يكن عليه بأس …","w":"السعدي","en":"When His words came down \"Indeed, those who consume the property of orphans unjustly are only consuming fire into their bellies, and they will be burned in a Blaze\", it was hard on the Muslims, and they separated their food from the orphans' food out of fear for themselves of touching it even in the way it was customary to share. They asked the Prophet ﷺ about that, and Allah told them that the aim is to set right the orphans' property by guarding it, keeping it safe and trading with it, and that mixing with them in food and other things is permitted provided it does not harm the orphans, because they are their brothers and it is the way of a brother to mix with his brother. The measure for that is intention and action: whoever Allah knows to intend to set right for the orphan and have no greed for his wealth, then if something enters by accident there is no blame upon him …"},{"bk":"saadi","s":4,"ay":10,"x":"ولما أمرهم بذلك زجرهم عن أكل أموال اليتامى وتوعَّد على ذلك أشد العذاب، فقال:{إنَّ الذين يأكلون أموال اليتامى ظلماً}؛ أي: بغير حق، وهذا القيد يخرُجُ به ما تقدَّم من جواز الأكل للفقير بالمعروف، ومن جواز خلط طعامهم بطعام اليتامى؛ فمن أكلها ظُلماً؛ فإنما {يأكلون في بطونهم ناراً}؛ أي: فإن الذي أكلوه نار تتأجَّج في أجوافهم، وهم الذين أدخلوه في بطونهم، {وسيصلون سعيراً}؛ أي: ناراً محرقة متوقدة.","w":"السعدي","en":"Having commanded them that, He warned them against consuming orphans' property and threatened the severest punishment for it. He said: \"Indeed, those who consume the property of orphans unjustly\" — that is, without right; and this qualification excludes what was mentioned before of the poor person eating by what is customary and mixing their food with the orphans'. Whoever consumes it unjustly is only \"consuming fire into their bellies\", that is, what they ate is a fire blazing in their insides, which they themselves put in their bellies, \"and they will be burned in a Blaze\", a burning, kindled fire."}],"h":["yatim"]},{"id":"ayama","ch":"ahl","t":"«وأنكحوا الأيامى منكم»: رعاية من فقد الزوج","e":"الأمر بإنكاح الأيامى وهم من لا زوج له، ووعد الله بالإغناء. ولفظ «الأرملة» بعينه لم يرد في القرآن، وورد في السنة.","ay":[[24,32,33]],"q":[{"bk":"saadi","s":24,"ay":32,"x":"يأمر تعالى الأولياء والأسيادَ بإنكاح مَنْ تحتَ ولايَتِهِم من الأيامى، وهم مَنْ لا أزواجَ لهم من رجالٍ ونساءٍ ثِيْبٍ وأبكارٍ، فيجب على القريب وولي اليتيم أن يزوِّجَ مَنْ يحتاجُ للزواج ممَّن تجبُ نفقته عليه، وإذا كانوا مأمورين بإنكاح مَنْ تحتَ أيديهم؛ كان أمرُهم بالنِّكاح بأنفسهم من باب أولى.","w":"السعدي","en":"Allah commands guardians and masters to marry off those under their guardianship who are unmarried — those who have no spouses, men and women, previously married and virgins. So it is obligatory for the relative and the orphan's guardian to marry off one who needs marriage from among those whose maintenance is his duty; and if they are commanded to marry off those under their hands, then their own marrying is more fitting."},{"bk":"saadi","s":24,"ay":32,"x":"وقوله:{إن يكونوا فقراءَ}؛ أي: الأزواج والمتزوِّجين، {يُغۡنِهِمُ الله من فضلِهِ}: فلا يمنعكم ما تتوهَّمون من أنَّه إذا تزوَّج افتقر بسبب كَثْرَةِ العائلة ونحوه.","w":"السعدي","en":"His words \"if they are poor\", that is, the husbands and those who marry, \"Allah will enrich them from His bounty\": so let not what you imagine hold you back, that when someone marries he becomes poor because of the size of the family and the like."}],"h":["armala"]},{"id":"asir","ch":"ahl","t":"«ويطعمون الطعام على حبه مسكيناً ويتيماً وأسيراً»","e":"وصف الأبرار بإطعام المسكين واليتيم والأسير على حب الطعام.","ay":[[76,8,10]],"q":[{"bk":"ibnkathir","s":76,"ay":8,"x":"وَفِي الصَّحِيحِ: \"أَفْضَلُ الصَّدَقَةِ أَنْ تَصَدّقَ وَأَنْتَ صَحِيحٌ، شَحِيحٌ، تَأْمَلُ الْغِنَى، وَتَخْشَى الْفَقْرَ\" أَيْ: فِي حَالِ مَحَبَّتِكَ لِلْمَالِ وَحِرْصِكَ عَلَيْهِ وَحَاجَتِكَ إِلَيْهِ؛ وَلِهَذَا قَالَ تَعَالَى: ﴿وَيُطْعِمُونَ الطَّعَامَ عَلَى حُبِّهِ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا﴾ أَمَّا الْمِسْكِينُ وَالْيَتِيمُ، فَقَدْ تَقَدَّمَ بَيَانُهُمَا وَصِفَتُهُمَا.","w":"ابن كثير","en":"And in the authentic report: \"The best charity is that you give while you are healthy, miserly, hoping for wealth and fearing poverty\", that is, while you love wealth and are eager for it and in need of it; and hence Allah said: \"And they feed food despite their love for it, the needy, the orphan and the captive.\" As for the needy and the orphan, their explanation and description have already been given."}],"h":[]},{"id":"ithar","ch":"qudwa","t":"«ويؤثرون على أنفسهم ولو كان بهم خصاصة»","e":"وصف الأنصار بإيثار غيرهم على أنفسهم مع الحاجة.","ay":[[59,9,9]],"q":[{"bk":"saadi","s":59,"ay":9,"x":"وهذا يدلُّ على سلامة صدورهم وانتفاء الغلِّ والحقد والحسد عنها، ويدلُّ ذلك على أنَّ المهاجرين أفضل من الأنصار؛ لأنَّ الله قدَّمهم بالذِّكر، وأخبر أنَّ الأنصارَ لا يجدون في صدورهم حاجةً مما أوتوا، فدلَّ على أنَّ الله تعالى آتاهم ما لم يؤتِ الأنصارَ ولا غيرهم، ولأنَّهم جمعوا بين النصرة والهجرة، وقوله:{ويؤثِرونَ على أنفسِهِم ولو كان بهم خَصاصةٌ}؛ أي: ومن أوصاف الأنصار التي فاقوا بها غيرهم وتميَّزوا بها عمَّن سواهم الإيثار، وهو أكمل أنواع الجود، وهو الإيثار بمحابِّ النفس من الأموال وغيرها، وبذلها للغيرِ، مع الحاجة إليها، بل مع الضَّرورة والخَصاصة، وهذا لا يكون إلا من خُلُقٍ زكيٍّ ومحبَّة لله تعالى مقدَّمة على [محبة] شهوات النفس ولذَّاتها.","w":"السعدي","en":"This indicates the soundness of their breasts and the absence of rancor, hatred and envy from them, and it indicates that the Muhajirun are better than the Ansar, because Allah put them first in mention and informed that the Ansar find no want in their hearts for what was given to them. It indicates that Allah gave them what He did not give the Ansar or anyone else, and because they combined support and migration. His words \"and they give preference over themselves, even though they are in privation\" mean: of the qualities of the Ansar by which they surpassed others and were distinguished from the rest is preferring others (ithar), which is the most perfect kind of generosity: preferring others in what the soul loves of wealth and other things and giving it to someone else while in need of it, indeed in dire need and privation. This does not come except from a pure character and a love of Allah that is placed before the soul's desires and pleasures."}],"h":[]},{"id":"dayf","ch":"qudwa","t":"إبراهيم عليه السلام وإكرام الضيف","e":"إكرام إبراهيم عليه السلام ضيوفه بعجل سمين.","ay":[[51,24,27],[11,69,69]],"q":[{"bk":"saadi","s":51,"ay":24,"x":"ولهذا راغ {إلى أهلِهِ}؛ أي: ذهب سريعاً في خفيةٍ ليحضر لهم قِراهم، {فجاء بعجلٍ سمينٍ}. {27}{فقرَّبه إليهم}: وعرض عليهم الأكل، فَـ {قَالَ ألا تأكُلونَ}؟","w":"السعدي","en":"Hence he turned aside \"to his family\", that is, he went quickly and unnoticed to bring them their hospitality, \"and brought a fat calf\". \"And he placed it near them\", offering them to eat, and said, \"Will you not eat?\""},{"bk":"saadi","s":11,"ay":69,"x":"إبراهيمُ لما دخلوا عليه، {أن جاء بعجل حنيذ}؛ أي: بادر لبيته فاستحضر لأضيافه عجلاً مشويًّا على الرَّضْفِ سميناً، فقرَّبه إليهم فقال: ألا تأكلونَ.","w":"السعدي","en":"Ibrahim, when they entered upon him, \"did not delay in bringing a roasted calf\", that is, he hastened to his house and brought for his guests a calf roasted on hot stones, fat; he brought it near them and said: \"Will you not eat?\""}],"h":[]},{"id":"nabi","ch":"qudwa","t":"«لقد كان لكم في رسول الله أسوة حسنة»: جود النبي ﷺ","e":"الأمر بالتأسّي برسول الله ﷺ في أقواله وأفعاله وأحواله.","ay":[[33,21,21]],"q":[{"bk":"ibnkathir","s":33,"ay":21,"x":"هَذِهِ الْآيَةُ الْكَرِيمَةُ أَصْلٌ كَبِيرٌ فِي التَّأَسِّي بِرَسُولِ اللَّهِ ﷺ فِي أَقْوَالِهِ وَأَفْعَالِهِ وَأَحْوَالِهِ؛ وَلِهَذَا أُمِرَ النَّاسُ بِالتَّأَسِّي بِالنَّبِيِّ ﷺ يَوْمَ الْأَحْزَابِ، فِي صَبْرِهِ وَمُصَابَرَتِهِ وَمُرَابَطَتِهِ وَمُجَاهَدَتِهِ وَانْتِظَارِهِ الْفَرَجَ مِنْ رَبِّهِ، عَزَّ وَجَلَّ، صَلَوَاتُ اللَّهِ وَسَلَامُهُ عَلَيْهِ دَائِمًا إِلَى يَوْمِ الدِّينِ؛ وَلِهَذَا قَالَ تَعَالَى لِلَّذِينِ تَقَلَّقُوا وَتَضْجَّرُوا وَتَزَلْزَلُوا وَاضْطَرَبُوا فِي أَمْرِهِمْ يَوْمَ الْأَحْزَابِ: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ﴾ أَيْ: هَلَّا اقْتَدَيْتُمْ بِهِ وَتَأَسَّيْتُمْ بِشَمَائِلِهِ؟","w":"ابن كثير","en":"This noble verse is a great foundation for following the Messenger of Allah ﷺ in his words, his actions and his states. Hence the people were commanded to follow the Prophet ﷺ on the day of the Confederates in his patience, perseverance, vigilance at the frontier, striving, and awaiting relief from his Lord, Mighty and Majestic, with Allah's blessings and peace upon him always until the Day of Judgment; and hence Allah said to those who were anxious, distressed, shaken and unsettled in their affair that day: \"You have in the Messenger of Allah an excellent example\", that is, why did you not follow him and take his character as your model?"}],"h":["jud"]},{"id":"musa","ch":"qudwa","t":"موسى عليه السلام: «فسقى لهما ثم تولى إلى الظل»","e":"سقي موسى عليه السلام للمرأتين دون طلب أجر ثم دعاؤه.","ay":[[28,23,24]],"q":[{"bk":"saadi","s":28,"ay":24,"x":"فرقَّ لهما موسى عليه السلام ورحِمَهما، {فسقى لهما}: غير طالبٍ منهما الأجرَ، ولا له قصدٌ غيرَ وجه الله تعالى، فلما سقى لهما، وكان ذلك وقت شدة حرِّ وسط النهار؛ بدليل قوله:{ثمَّ تولَّى إلى الظِّلِّ}؛ مستريحاً لتلك الظلال بعد التعب، {فقال} في تلك الحالة مسترزقاً ربَّه: {ربِّ إنِّي لما أنزلتَ إليَّ من خيرٍ فقيرٌ}؛ أي: إنِّي مفتقرٌ للخير الذي تسوقُهُ إليَّ وتيسِّرُه لي، وهذا سؤالٌ منه بحالِهِ، والسؤال بالحال أبلغُ من السؤال بلسان المقال.","w":"السعدي","en":"Musa (peace be upon him) felt compassion and mercy for them, \"so he watered for them\", not asking payment from them and with no aim other than the face of Allah, the Exalted. When he had watered, and that was at the time of intense heat, midday, as shown by His words \"then he turned back to the shade\", resting in that shade after fatigue, \"he said\", in that condition asking his Lord for provision: \"My Lord, indeed I am, for whatever good You would send down to me, in need\", that is, I am in need of the good that You drive to me and make easy for me; and this is a request by his condition, and a request by condition is more eloquent than a request in spoken words."}],"h":[]},{"id":"layl","ch":"qudwa","t":"«فأما من أعطى واتقى وصدّق بالحسنى»","e":"وصف من أعطى واتقى وصدّق بالحسنى وتيسيره لليسرى.","ay":[[92,5,7],[92,17,21]],"q":[{"bk":"saadi","s":92,"ay":5,"x":"ولهذا فصَّل الله العاملين ووصف أعمالهم، فقال:{فأمَّا من أعطى}؛ أي: ما أمر به من العبادات الماليَّة كالزَّكوات والنَّفقات والكفَّارات والصَّدقات والإنفاق في وجوه الخير، والعبادات البدنيَّة كالصَّلاة والصوم وغيرهما ، والمركَّبة من ذلك كالحجِّ والعمرة ونحوهما، {واتَّقى}: ما نُهِي عنه من المحرَّمات والمعاصي على اختلاف أجناسها، {وصدَّق بالحُسنى}؛ أي: صدَّق بلا إله إلاَّ الله، وما دلَّت عليه من [جميع] العقائد الدينيَّة وما ترتَّب عليها من الجزاء [الأخروي]، {فسنيسِّره لليُسرى}؛ أي: نيسِّر له أمره ونجعله مسهَّلاً عليه كلُّ خيرٍ، ميسَّراً له ترك كلِّ شرٍّ؛ لأنَّه أتى بأسباب التيسير، فيسَّر الله له ذلك.","w":"السعدي","en":"That is why Allah detailed the doers and described their deeds, saying: \"As for he who gives\", that is, what he was commanded of financial worship such as zakat, maintenance, expiations, charity and spending in ways of good, and bodily worship such as prayer and fasting, and the combined such as hajj and umrah, \"and fears Allah\", avoiding what he was forbidden of prohibitions and sins of all kinds, \"and believes in the best\", that is, believes in \"there is no god but Allah\" and all the creed it indicates and the recompense in the Hereafter that follows it, \"We will ease him toward ease\", that is, We will make his affair easy and make every good easy for him, and leaving every evil easy for him, because he brought the causes of ease, so Allah made that easy for him."}],"h":[]},{"id":"jariya","ch":"jaza","t":"«ونكتب ما قدّموا وآثارهم»","e":"كتابة ما قدّمه الإنسان وآثاره التي تبقى بعد موته.","ay":[[36,12,12]],"q":[{"bk":"saadi","s":36,"ay":12,"x":"{إنَّا نحنُ نُحۡيي الموتى}؛ أي: نبعثُهم بعد موتِهِم لِنُجازِيَهم على الأعمال، {ونَكۡتُبُ ما قَدَّموا}: من الخير والشرِّ، وهو أعمالُهم التي عملوها وباشَروها في حال حياتِهِم، {وآثارَهُم}: وهي آثار الخير وآثارُ الشرِّ التي كانوا هم السببَ في إيجادها في حال حياتِهِم وبعدَ وفاتِهِم، وتلك الأعمال التي نشأت من أقوالِهِم وأفعالِهِم وأحوالِهِم؛ فكلُّ خيرٍ عمل به أحدٌ من الناس بسبب علم العبد وتعليمِهِ أو نُصحه أو أمرِهِ بالمعروف أو نهيِهِ عن المنكر أو علم أوْدَعَه عند المتعلِّمين أو في كتبٍ يُنْتَفَع بها في حياتِهِ وبعدَ موتِهِ أو عمل خيراً من صلاةٍ أو زكاةٍ أو صدقةٍ أو إحسانٍ فاقتدى به غيرُه، أو عمل مسجداً أو محلاًّ من المحالِّ التي يرتَفِقُ بها الناسُ وما أشبهَ ذلك؛ فإنَّها من آثارِهِ التي تُكْتَبُ له …","w":"السعدي","en":"\"Indeed, it is We who bring the dead to life\", that is, We resurrect them after their death so that We may recompense them for their deeds, \"and We record what they sent ahead\", of good and bad, which are their deeds that they did and performed during their lives, \"and their traces\", which are the traces of good and traces of evil that they were the cause of existing during their lives and after their death, and those deeds arose from their words, actions and states. So every good that someone acts upon because of a servant's knowledge and teaching, or his advice, or his enjoining good or forbidding evil, or knowledge he entrusted to learners or in books that are benefited from during his life and after his death, or a good deed such as prayer, zakat, charity or kindness that others then emulate, or a mosque he built or a place people use — these are among his traces that are recorded for him …"}],"h":["jariya","ghars"]},{"id":"yukhlifu","ch":"jaza","t":"«وما أنفقتم من شيء فهو يخلفه»","e":"وعد الله بإخلاف ما يُنفَق.","ay":[[34,39,39]],"q":[{"bk":"saadi","s":34,"ay":39,"x":"ثم أعادَ تعالى أنه {يَبۡسُطُ الرزقَ لِمَن يشاءُ مِنۡ عبادِه ويَقۡدِرُ له}: ويَقْدِرُ له ليرتِّبَ عليه قوله: {وما أنفَقۡتُم من شيء}: نفقةً واجبةً أو مستحبَّةً على قريب أو جارٍ أو مسكينٍ أو يتيم أو غير ذلك، {فهو} تعالى {يُخۡلِفُهُ}: فلا تتوهَّموا أنَّ الإنفاق مما يُنْقِصُ الرزق، بل وعد بالخلف للمنفق الذي يبسط الرزق لمن يشاءُ ويَقْدِرُ.","w":"السعدي","en":"Then He repeated that He \"extends provision for whom He wills of His servants and restricts it for him\", so that He could follow with His words: \"And whatever you spend of anything, He will replace it\", whether obligatory or recommended spending on a relative, neighbor, needy person, orphan or other. So do not imagine that spending decreases provision; rather He promised replacement to the one who spends, He who extends provision for whom He wills and restricts it."}],"h":[]},{"id":"tijara","ch":"jaza","t":"«يرجون تجارة لن تبور»","e":"وصف التالين لكتاب الله المنفقين سرّاً وعلانية بتجارة لن تبور.","ay":[[35,29,30]],"q":[{"bk":"saadi","s":35,"ay":29,"x":"{إنَّ الذين يتلونَ كتاب الله}؛ أي: يتَّبعونَه في أوامره فيمتَثِلونها وفي نواهيه فيترُكونها وفي أخبارِهِ فيصدِّقونها ويعتَقِدونها ولا يقدِّمون عليه ما خالَفَه من الأقوال، ويتلون أيضاً ألفاظَه بدراستِهِ، ومعانِيه بتتبُّعِها واستخراجِها، ثم خصَّ من التلاوة بعدما عمَّ الصلاةَ ـ التي هي عمادُ الدِّين ونورُ المسلمين وميزانُ الإيمان وعلامةُ صدق الإسلام ـ النفقةَ على الأقارب والمساكين واليتامى وغيرهم من الزكاة والكفارات والنذور والصدقات، {سرًّا وعلانيةً}: في جميع الأوقات؛ {يرجونَ}: بذلك {تجارةً لن تبورَ}؛ أي: لن تكسدَ وتفسدَ، بل تجارة هي أجلُّ التجاراتِ وأعلاها وأفضلُها ألا وهي رضا ربِّهم والفوزُ بجزيل ثوابِهِ والنجاةُ من سخطِهِ وعقابِهِ، وهذا فيه الإخلاصُ بأعمالهم، وأنَّهم لا يرجون بها من المقاصدِ السيئةِ والنيَّاتِ الفاسدةِ شيئاً.","w":"السعدي","en":"\"Indeed, those who recite the Book of Allah\", that is, follow it in its commands, carrying them out, in its prohibitions, abandoning them, and in its reports, believing them and holding them as creed, putting nothing that contradicts it of sayings ahead of it; and they also recite its words by studying them and its meanings by pursuing and deriving them. Then, after mentioning prayer in general terms — which is the pillar of religion, the light of the Muslims, the scale of faith and the sign of the sincerity of Islam — He singled out spending on relatives, the needy, orphans and others, of zakat, expiations, vows and charity, \"secretly and publicly\" at all times; \"they hope\" by that \"for a trade that will never perish\", that is, will never go slack and spoil, but a trade that is the most exalted, highest and best of trades: the pleasure of their Lord, success in His abundant reward and safety from His wrath and punishment. And in this is the sincerity of their deeds, and that they seek nothing of evil aims and corrupt intentions by them."}],"h":[]},{"id":"yurbi","ch":"jaza","t":"«ويربي الصدقات»","e":"محق الربا وتنمية الصدقات.","ay":[[2,276,276]],"q":[{"bk":"saadi","s":2,"ay":276,"x":"ثم أخبر تعالى أنه يمحق مكاسب المرابين ويربي صدقات المنفقين، عكس ما يتبادر لأذهان كثير من الخلق أن الإنفاق ينقص المال وأن الربا يزيده، فإن مادة الرزق وحصول ثمراته من الله تعالى، وما عند الله لا ينال إلا بطاعته وامتثال أمره، فالمتجرئ على الربا يعاقبه بنقيض مقصوده، وهذا مشاهد بالتجربة ومن أصدق من الله قيلاً {والله لا يحب كل كفار أثيم}؛ وهو الذي كفر نعمة الله، وجحد منَّة ربه وأثم بإصراره على معاصيه.","w":"السعدي","en":"Then He informed that He eliminates the gains of those who deal in usury and makes the charity of those who spend grow, the opposite of what comes to the minds of many people, that spending decreases wealth and usury increases it. For the substance of provision and the achievement of its fruits are from Allah, and what is with Allah is attained only by obeying Him and carrying out His command. So one who dares to deal in usury, He punishes with the opposite of his aim, and this is observed by experience, \"and who is more truthful than Allah in speech?\" — \"And Allah does not like every sinning disbeliever\", that is, one who has denied the favor of Allah, rejected the kindness of his Lord and sinned by persisting in disobedience."}],"h":[]},{"id":"tuhhir","ch":"jaza","t":"«خذ من أموالهم صدقة تطهّرهم وتزكّيهم بها»","e":"أخذ الصدقة من أموال المؤمنين تطهيراً لهم وتزكية.","ay":[[9,103,103]],"q":[{"bk":"saadi","s":9,"ay":103,"x":"قال تعالى لرسوله ومَنْ قام مقامه آمراً له بما يطهِّر المؤمنين ويتمِّم إيمانهم: {خُذۡ من أموالهم صدقةً}: وهي الزكاة المفروضة، {تطهِّرُهم وتزكِّيهم بها}؛ أي: تطهِّرهم من الذُّنوب والأخلاق الرذيلة، {وتزكِّيهم}؛ أي: تنميهم، وتزيد في أخلاقهم الحسنة وأعمالهم الصالحة، وتزيد في ثوابهم الدنيوي والأخروي، وتنمي أموالهم، {وصَلِّ عليهم}؛ أي: ادع لهم؛ أي: للمؤمنين عموماً وخصوصاً عندما يدفعون إليك زكاة أموالهم.","w":"السعدي","en":"Allah said to His Messenger and whoever takes his place, commanding him with what purifies the believers and perfects their faith: \"Take from their wealth a charity\", which is the obligatory zakat, \"by which you purify them and cause them increase\", that is, purify them from sins and bad character, \"and cause them to grow\", that is, make them grow, increase their good character and righteous deeds, and increase their reward in this world and the next, and cause their wealth to grow, \"and invoke blessings upon them\", that is, supplicate for them, for the believers in general and especially when they bring you the zakat of their wealth."}],"h":[]},{"id":"bukhl","ch":"jaza","t":"«ولا يحسبنّ الذين يبخلون بما آتاهم الله من فضله»","e":"وعيد من يبخل بما آتاه الله وبيان أن البخل على النفس.","ay":[[3,180,180],[47,38,38]],"q":[{"bk":"saadi","s":3,"ay":180,"x":"أي: ولا يظن الذين يبخلون؛ أي: يمنعون ما عندهم مما آتاهم الله من فضله من المال والجاه والعلم وغير ذلك، مما منحهم الله وأحسن إليهم به، وأمرهم ببذل ما لا يضرهم منه لعباده فبخلوا بذلك، وأمسكوه وضنوا به على عباد الله، وظنوا أنه خير لهم بل هو شر لهم في دينهم ودنياهم وعاجلهم وآجلهم، {سيطوقون ما بخلوا به يوم القيامة}؛ أي يجعل ما بخلوا به طوقاً في أعناقهم يعذبون به كما ورد في الحديث الصحيح:«إن البخيل يمثل له ماله يوم القيامة شجاعاً أقرع له زبيبتان يأخذ بلهزمته يقول: أنا مالك، أنا كنزك»، وتلا رسول الله - صلى الله عليه وسلم - مصداق ذلك هذه الآية، فهؤلاء حسبوا أن بخلهم نافعهم ومجدٍ عليهم فانقلب عليهم الأمر …","w":"السعدي","en":"That is, let not those who are miserly think — those who withhold what they have of what Allah gave them of His bounty, of wealth, rank, knowledge and other things that Allah granted them and was good to them with, and commanded them to give from what does not harm them to His servants, but they were stingy with it, withheld it and held it back from Allah's servants — and they thought it was good for them; rather it is bad for them in their religion and their worldly life, in their immediate and later affairs. \"They will be encircled by what they withheld on the Day of Resurrection\", that is, what they withheld will be made a collar around their necks by which they are punished, as in the authentic hadith: \"The miser's wealth will be made for him on the Day of Resurrection into a bald serpent with two black spots, taking him by the jaws and saying: I am your wealth, I am your treasure\"; and the Messenger of Allah ﷺ recited this verse as confirmation of that. So these thought their miserliness would benefit them and avail them, but the matter turned against them …"}],"h":[]},{"id":"kanz","ch":"jaza","t":"«والذين يكنزون الذهب والفضة ولا ينفقونها في سبيل الله»","e":"الوعيد في كنز الذهب والفضة دون إنفاقها في سبيل الله.","ay":[[9,34,35]],"q":[{"bk":"saadi","s":9,"ay":34,"x":"وذكر الله في هاتين الآيتين انحراف الإنسان في ماله، وذلك بأحد أمرين: إما أن ينفِقَه في الباطل الذي لا يُجدي عليه نفعاً، بل لا ينالُه منه إلا الضرر المحض، وذلك كإخراج الأموال في المعاصي والشَّهوات التي لا تُعين على طاعة الله، وإخراجها للصدِّ عن سبيل الله. وإما أن يمسِكَ ماله عن إخراجِهِ في الواجبات، والنهي عن الشيء أمرٌ بضدِّه.","w":"السعدي","en":"In these two verses Allah mentioned a person's deviation in his wealth, which is in one of two ways: either he spends it on falsehood that is of no benefit to him, rather he gets from it only pure harm, such as spending wealth on sins and desires that do not help obedience to Allah, and spending it to bar from the path of Allah; or he withholds his wealth from being spent on obligations; and the prohibition of something is an order for its opposite."}],"h":[]},{"id":"asabu","ch":"jaza","t":"أصحاب الجنة: «لا يدخلنّها اليوم عليكم مسكين»","e":"قصة أصحاب الجنة الذين تواصوا بمنع المساكين فهلكت جنتهم.","ay":[[68,17,33]],"q":[{"bk":"saadi","s":68,"ay":17,"x":"{فانطلقوا}: قاصدين لها ، {وهم يتخافتونَ}: فيما بينهم بمنع حقِّ الله تعالى، ويقولون:{لا يَدۡخُلَنَّها اليومَ عليكم مسكينٌ}؛ أي: بكِّروا قبل انتشار الناس، وتواصوا مع ذلك بمنع الفقراء والمساكين.","w":"السعدي","en":"\"So they set out\", intending it, \"while whispering among themselves\", to withhold Allah's right, and saying: \"Today no needy person will enter it upon you\", that is, go early before people spread out, and in addition to that they urged each other to keep the poor and needy away."}],"h":[]}],"ay":{"226":"فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","251":"مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضۡعَافٗا كَثِيرَةٗۚ وَٱللَّهُ يَقۡبِضُ وَيَبۡصُۜطُ وَإِلَيۡهِ تُرۡجَعُونَ","260":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِمَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ يَوۡمٞ لَّا بَيۡعٞ فِيهِ وَلَا خُلَّةٞ وَلَا شَفَٰعَةٞۗ وَٱلۡكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ","267":"مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِي كُلِّ سُنۢبُلَةٖ مِّاْئَةُ حَبَّةٖۗ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ","268":"ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ فِي سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتۡبِعُونَ مَآ أَنفَقُواْ مَنّٗا وَلَآ أَذٗى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","269":"۞ قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ","270":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُبۡطِلُواْ صَدَقَٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِي يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَيۡهِ تُرَابٞ فَأَصَابَهُۥ وَابِلٞ فَتَرَكَهُۥ صَلۡدٗاۖ لَّا يَقۡدِرُونَ عَلَىٰ شَيۡءٖ مِّمَّا كَسَبُواْۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ","271":"وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِيتٗا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلٞ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَيۡنِ فَإِن لَّمۡ يُصِبۡهَا وَابِلٞ فَطَلّٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٌ","273":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ","277":"إِن تُبۡدُواْ ٱلصَّدَقَٰتِ فَنِعِمَّا هِيَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَآءَ فَهُوَ خَيۡرٞ لَّكُمۡۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","279":"لِلۡفُقَرَآءِ ٱلَّذِينَ أُحۡصِرُواْ فِي سَبِيلِ ٱللَّهِ لَا يَسۡتَطِيعُونَ ضَرۡبٗا فِي ٱلۡأَرۡضِ يَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِيمَٰهُمۡ لَا يَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافٗاۗ وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ","280":"ٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُم بِٱلَّيۡلِ وَٱلنَّهَارِ سِرّٗا وَعَلَانِيَةٗ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ","282":"يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ وَيُرۡبِي ٱلصَّدَقَٰتِۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ","425":"۞ وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ","426":"ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ وَٱلۡكَٰظِمِينَ ٱلۡغَيۡظَ وَٱلۡعَافِينَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ","472":"وَلَا يَحۡسَبَنَّ ٱلَّذِينَ يَبۡخَلُونَ بِمَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَيۡرٗا لَّهُمۖ بَلۡ هُوَ شَرّٞ لَّهُمۡۖ سَيُطَوَّقُونَ مَا بَخِلُواْ بِهِۦ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","502":"إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا","1268":"۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ","1269":"يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ","1294":"۞ إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ فَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","1337":"خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","1541":"وَلَقَدۡ جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞۖ فَمَا لَبِثَ أَن جَآءَ بِعِجۡلٍ حَنِيذٖ","2056":"وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا","2057":"وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا","2822":"وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ وَٱلصَّٰلِحِينَ مِنۡ عِبَادِكُمۡ وَإِمَآئِكُمۡۚ إِن يَكُونُواْ فُقَرَآءَ يُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","2823":"وَلۡيَسۡتَعۡفِفِ ٱلَّذِينَ لَا يَجِدُونَ نِكَاحًا حَتَّىٰ يُغۡنِيَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِينَ يَبۡتَغُونَ ٱلۡكِتَٰبَ مِمَّا مَلَكَتۡ أَيۡمَٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِيهِمۡ خَيۡرٗاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِيٓ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُواْ فَتَيَٰتِكُمۡ عَلَى ٱلۡبِغَآءِ إِنۡ أَرَدۡنَ تَحَصُّنٗا لِّتَبۡتَغُواْ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَمَن يُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَٰهِهِنَّ غَفُورٞ رَّحِيمٞ","2921":"وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ وَكَانَ بَيۡنَ ذَٰلِكَ قَوَامٗا","3274":"وَلَمَّا وَرَدَ مَآءَ مَدۡيَنَ وَجَدَ عَلَيۡهِ أُمَّةٗ مِّنَ ٱلنَّاسِ يَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَيۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِي حَتَّىٰ يُصۡدِرَ ٱلرِّعَآءُۖ وَأَبُونَا شَيۡخٞ كَبِيرٞ","3275":"فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ","3553":"لَّقَدۡ كَانَ لَكُمۡ فِي رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةٞ لِّمَن كَانَ يَرۡجُواْ ٱللَّهَ وَٱلۡيَوۡمَ ٱلۡأٓخِرَ وَذَكَرَ ٱللَّهَ كَثِيرٗا","3644":"قُلۡ إِنَّ رَبِّي يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ مِنۡ عِبَادِهِۦ وَيَقۡدِرُ لَهُۥۚ وَمَآ أَنفَقۡتُم مِّن شَيۡءٖ فَهُوَ يُخۡلِفُهُۥۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ","3688":"إِنَّ ٱلَّذِينَ يَتۡلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ يَرۡجُونَ تِجَٰرَةٗ لَّن تَبُورَ","3689":"لِيُوَفِّيَهُمۡ أُجُورَهُمۡ وَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورٞ شَكُورٞ","3716":"إِنَّا نَحۡنُ نُحۡيِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡۚ وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ فِيٓ إِمَامٖ مُّبِينٖ","4582":"هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ تُدۡعَوۡنَ لِتُنفِقُواْ فِي سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبۡخَلُۖ وَمَن يَبۡخَلۡ فَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ وَإِن تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ ثُمَّ لَا يَكُونُوٓاْ أَمۡثَٰلَكُم","4693":"وَفِيٓ أَمۡوَٰلِهِمۡ حَقّٞ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","4698":"هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ","4699":"إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ قَوۡمٞ مُّنكَرُونَ","4700":"فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلٖ سَمِينٖ","4701":"فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ","5081":"ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُواْ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِينَ فِيهِۖ فَٱلَّذِينَ ءَامَنُواْ مِنكُمۡ وَأَنفَقُواْ لَهُمۡ أَجۡرٞ كَبِيرٞ","5082":"وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ يَدۡعُوكُمۡ لِتُؤۡمِنُواْ بِرَبِّكُمۡ وَقَدۡ أَخَذَ مِيثَٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","5083":"هُوَ ٱلَّذِي يُنَزِّلُ عَلَىٰ عَبۡدِهِۦٓ ءَايَٰتِۭ بَيِّنَٰتٖ لِّيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ لَرَءُوفٞ رَّحِيمٞ","5084":"وَمَا لَكُمۡ أَلَّا تُنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ لَا يَسۡتَوِي مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ وَقَٰتَلَۚ أُوْلَٰٓئِكَ أَعۡظَمُ دَرَجَةٗ مِّنَ ٱلَّذِينَ أَنفَقُواْ مِنۢ بَعۡدُ وَقَٰتَلُواْۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرٞ","5085":"مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجۡرٞ كَرِيمٞ","5134":"وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةٗ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةٞۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","5143":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسٞ مَّا قَدَّمَتۡ لِغَدٖۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا تَعۡمَلُونَ","5196":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُلۡهِكُمۡ أَمۡوَٰلُكُمۡ وَلَآ أَوۡلَٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ","5197":"وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم مِّن قَبۡلِ أَن يَأۡتِيَ أَحَدَكُمُ ٱلۡمَوۡتُ فَيَقُولَ رَبِّ لَوۡلَآ أَخَّرۡتَنِيٓ إِلَىٰٓ أَجَلٖ قَرِيبٖ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّٰلِحِينَ","5198":"وَلَن يُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَآءَ أَجَلُهَاۚ وَٱللَّهُ خَبِيرُۢ بِمَا تَعۡمَلُونَ","5214":"فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُواْ وَأَطِيعُواْ وَأَنفِقُواْ خَيۡرٗا لِّأَنفُسِكُمۡۗ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","5287":"إِنَّا بَلَوۡنَٰهُمۡ كَمَا بَلَوۡنَآ أَصۡحَٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُواْ لَيَصۡرِمُنَّهَا مُصۡبِحِينَ","5288":"وَلَا يَسۡتَثۡنُونَ","5289":"فَطَافَ عَلَيۡهَا طَآئِفٞ مِّن رَّبِّكَ وَهُمۡ نَآئِمُونَ","5290":"فَأَصۡبَحَتۡ كَٱلصَّرِيمِ","5291":"فَتَنَادَوۡاْ مُصۡبِحِينَ","5292":"أَنِ ٱغۡدُواْ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَٰرِمِينَ","5293":"فَٱنطَلَقُواْ وَهُمۡ يَتَخَٰفَتُونَ","5294":"أَن لَّا يَدۡخُلَنَّهَا ٱلۡيَوۡمَ عَلَيۡكُم مِّسۡكِينٞ","5295":"وَغَدَوۡاْ عَلَىٰ حَرۡدٖ قَٰدِرِينَ","5296":"فَلَمَّا رَأَوۡهَا قَالُوٓاْ إِنَّا لَضَآلُّونَ","5297":"بَلۡ نَحۡنُ مَحۡرُومُونَ","5298":"قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ","5299":"قَالُواْ سُبۡحَٰنَ رَبِّنَآ إِنَّا كُنَّا ظَٰلِمِينَ","5300":"فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضٖ يَتَلَٰوَمُونَ","5301":"قَالُواْ يَٰوَيۡلَنَآ إِنَّا كُنَّا طَٰغِينَ","5302":"عَسَىٰ رَبُّنَآ أَن يُبۡدِلَنَا خَيۡرٗا مِّنۡهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ","5303":"كَذَٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ","5398":"وَٱلَّذِينَ فِيٓ أَمۡوَٰلِهِمۡ حَقّٞ مَّعۡلُومٞ","5399":"لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ","5494":"۞ إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَيۡكُمۡۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ فَٱقۡرَءُواْ مَا تَيَسَّرَ مِنۡهُۚ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ وَأَقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗاۚ وَمَا تُقَدِّمُواْ لِأَنفُسِكُم مِّنۡ خَيۡرٖ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيۡرٗا وَأَعۡظَمَ أَجۡرٗاۚ وَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ","5598":"وَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا","5599":"إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا","5600":"إِنَّا نَخَافُ مِن رَّبِّنَا يَوۡمًا عَبُوسٗا قَمۡطَرِيرٗا","6013":"كـَلَّآۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكّٗا دَكّٗا","6014":"وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا","6015":"وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذٖ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ","6016":"يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي","6062":"فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ","6063":"وَصَدَّقَ بِٱلۡحُسۡنَىٰ","6064":"فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ","6074":"وَسَيُجَنَّبُهَا ٱلۡأَتۡقَى","6075":"ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ","6076":"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ","6077":"إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ","6078":"وَلَسَوۡفَ يَرۡضَىٰ"},"h":{"khalaf":{"id":"khalaf","t":"دعاء الملَكين للمنفق والممسك","x":"مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلاَّ مَلَكَانِ يَنْزِلاَنِ فَيَقُولُ أَحَدُهُمَا اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الآخَرُ اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا","b":"bukhari","k":"1442","gr":"صحيح","en":"No day dawns upon the servants but that two angels descend; one says, 'O Allah, give the one who spends a replacement,' and the other says, 'O Allah, give the one who withholds ruin.'"},"naqas":{"id":"naqas","t":"الصدقة لا تنقص المال","x":"مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلاَّ عِزًّا وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلاَّ رَفَعَهُ اللَّهُ","b":"muslim","k":"2588","gr":"صحيح","en":"Charity does not decrease wealth; and Allah increases a servant who forgives only in honor; and no one humbles himself for Allah but Allah raises him."},"shiqq":{"id":"shiqq","t":"اتقوا النار ولو بشق تمرة","x":"اتَّقُوا النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ","b":"bukhari","k":"1417","gr":"صحيح","en":"Shield yourselves from the Fire, even with half a date."},"qaddam":{"id":"qaddam","t":"مالك ما قدّمت ومال وارثك ما أخّرت","x":"أَيُّكُمْ مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالِهِ \". قَالُوا يَا رَسُولَ اللَّهِ مَا مِنَّا أَحَدٌ إِلاَّ مَالُهُ أَحَبُّ إِلَيْهِ. قَالَ \" فَإِنَّ مَالَهُ مَا قَدَّمَ، وَمَالُ وَارِثِهِ مَا أَخَّرَ","b":"bukhari","k":"6442","gr":"صحيح","en":"\"Which of you loves the wealth of his heir more than his own wealth?\" They said, \"O Messenger of Allah, there is none of us who does not love his own wealth more.\" He said, \"Indeed his wealth is what he sent ahead, and the wealth of his heir is what he left behind.\""},"mali":{"id":"mali","t":"ليس لك من مالك إلا ما أكلت وما لبست وما تصدقت","x":"يَقُولُ ابْنُ آدَمَ مَالِي مَالِي - قَالَ - وَهَلْ لَكَ يَا ابْنَ آدَمَ مِنْ مَالِكَ إِلاَّ مَا أَكَلْتَ فَأَفْنَيْتَ أَوْ لَبِسْتَ فَأَبْلَيْتَ أَوْ تَصَدَّقْتَ فَأَمْضَيْتَ","b":"muslim","k":"2958","gr":"صحيح","en":"The son of Adam says, \"My wealth, my wealth!\" — He said — \"And do you have, O son of Adam, of your wealth anything except what you ate and consumed, or wore and wore out, or gave in charity and so sent forward?\""},"sirr":{"id":"sirr","t":"من تصدّق فأخفى صدقته","x":"سَبْعَةٌ يُظِلُّهُمُ اللَّهُ تَعَالَى فِي ظِلِّهِ يَوْمَ لاَ ظِلَّ إِلاَّ ظِلُّهُ إِمَامٌ عَدْلٌ، وَشَابٌّ نَشَأَ فِي عِبَادَةِ اللَّهِ، وَرَجُلٌ قَلْبُهُ مُعَلَّقٌ فِي الْمَسَاجِدِ، وَرَجُلاَنِ تَحَابَّا فِي اللَّهِ اجْتَمَعَا عَلَيْهِ وَتَفَرَّقَا عَلَيْهِ، وَرَجُلٌ دَعَتْهُ امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ فَقَالَ إِنِّي أَخَافُ اللَّهَ، وَرَجُلٌ تَصَدَّقَ بِصَدَقَةٍ فَأَخْفَاهَا حَتَّى لاَ تَعْلَمَ شِمَالُهُ مَا تُنْفِقُ يَمِينُهُ، وَرَجُلٌ ذَكَرَ اللَّهَ خَالِيًا فَفَاضَتْ عَيْنَاهُ","b":"bukhari","k":"1423","gr":"صحيح","en":"\"Seven will be shaded by Allah, the Exalted, in His shade on the day when there is no shade but His: a just ruler; a youth who grew up in the worship of Allah; a man whose heart is attached to the mosques; two men who love each other for Allah, meeting for it and parting for it; a man whom a woman of rank and beauty invites and he says, 'I fear Allah'; a man who gives charity and conceals it so that his left hand does not know what his right hand spends; and a man who remembers Allah in solitude and his eyes overflow.\""},"fadl2":{"id":"fadl2","t":"بذل الفضل خير","x":"يَا ابْنَ آدَمَ إِنَّكَ أَنْ تَبْذُلَ الْفَضْلَ خَيْرٌ لَكَ وَأَنْ تُمْسِكَهُ شَرٌّ لَكَ وَلاَ تُلاَمُ عَلَى كَفَافٍ وَابْدَأْ بِمَنْ تَعُولُ وَالْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى","b":"muslim","k":"1036","gr":"صحيح","en":"\"O son of Adam, if you give away your surplus it is better for you, and if you withhold it, it is worse for you; and you are not blamed for what is just sufficient. Begin with those you support; and the upper hand is better than the lower hand.\""},"fadl":{"id":"fadl","t":"من كان معه فضل فليعد به على من لا شيء له","x":"مَنْ كَانَ مَعَهُ فَضْلُ ظَهْرٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لاَ ظَهْرَ لَهُ وَمَنْ كَانَ لَهُ فَضْلٌ مِنْ زَادٍ فَلْيَعُدْ بِهِ عَلَى مَنْ لاَ زَادَ لَهُ","b":"muslim","k":"1728","gr":"صحيح","en":"\"Whoever has a surplus mount, let him give it to the one who has no mount; and whoever has a surplus of provisions, let him give it to the one who has no provisions.\""},"miskin":{"id":"miskin","t":"من هو المسكين","x":"لَيْسَ الْمِسْكِينُ الَّذِي يَطُوفُ عَلَى النَّاسِ تَرُدُّهُ اللُّقْمَةُ وَاللُّقْمَتَانِ وَالتَّمْرَةُ وَالتَّمْرَتَانِ، وَلَكِنِ الْمِسْكِينُ الَّذِي لاَ يَجِدُ غِنًى يُغْنِيهِ، وَلاَ يُفْطَنُ بِهِ فَيُتَصَدَّقُ عَلَيْهِ، وَلاَ يَقُومُ فَيَسْأَلُ النَّاسَ","b":"bukhari","k":"1479","gr":"صحيح","en":"\"The needy person is not the one who goes around among the people and is turned away with a morsel or two, a date or two; but the needy person is the one who does not find enough to suffice him, and is not noticed so that charity could be given to him, and does not stand up to beg from people.\""},"yatim":{"id":"yatim","t":"كافل اليتيم في الجنة","x":"أَنَا وَكَافِلُ الْيَتِيمِ فِي الْجَنَّةِ هَكَذَا \". وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى، وَفَرَّجَ بَيْنَهُمَا شَيْئًا","b":"bukhari","k":"5304","gr":"صحيح","en":"\"I and the sponsor of an orphan will be in Paradise like this\" — and he pointed with his index and middle fingers, spreading them slightly apart."},"armala":{"id":"armala","t":"الساعي على الأرملة والمسكين","x":"السَّاعِي عَلَى الأَرْمَلَةِ وَالْمِسْكِينِ كَالْمُجَاهِدِ فِي سَبِيلِ اللَّهِ، أَوِ الْقَائِمِ اللَّيْلَ الصَّائِمِ النَّهَارَ","b":"bukhari","k":"5353","gr":"صحيح","en":"\"The one who strives for the widow and the needy is like the fighter in the way of Allah, or like the one who stands in prayer by night and fasts by day.\""},"jud":{"id":"jud","t":"جود النبي ﷺ","x":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَجْوَدَ النَّاسِ، وَكَانَ أَجْوَدُ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ جِبْرِيلُ، وَكَانَ يَلْقَاهُ فِي كُلِّ لَيْلَةٍ مِنْ رَمَضَانَ فَيُدَارِسُهُ الْقُرْآنَ، فَلَرَسُولُ اللَّهِ صلى الله عليه وسلم أَجْوَدُ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ","b":"bukhari","k":"6","gr":"صحيح","en":"The Messenger of Allah ﷺ was the most generous of people, and he was at his most generous in Ramadan when Jibril met him, and Jibril would meet him every night of Ramadan and review the Quran with him. Truly the Messenger of Allah ﷺ was more generous in giving good than the blowing wind."},"ghars":{"id":"ghars","t":"الغرس صدقة جارية","x":"مَا مِنْ مُسْلِمٍ يَغْرِسُ غَرْسًا، أَوْ يَزْرَعُ زَرْعًا، فَيَأْكُلُ مِنْهُ طَيْرٌ أَوْ إِنْسَانٌ أَوْ بَهِيمَةٌ، إِلاَّ كَانَ لَهُ بِهِ صَدَقَةٌ","b":"bukhari","k":"2320","gr":"صحيح","en":"\"There is no Muslim who plants a tree or sows a crop, and a bird, a person or an animal eats from it, but that it is charity for him.\""},"jariya":{"id":"jariya","t":"انقطاع العمل إلا من ثلاث","x":"إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلاَّ مِنْ ثَلاَثَةٍ إِلاَّ مِنْ صَدَقَةٍ جَارِيَةٍ أَوْ عِلْمٍ يُنْتَفَعُ بِهِ أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ","b":"muslim","k":"1631","gr":"صحيح","en":"\"When a person dies, his deeds come to an end except for three: ongoing charity, knowledge that is benefited from, or a righteous child who prays for him.\""}},"nay":88,"nq":45,"nh":14};
